ProjectALife.DialogueShards["replies_ask_5"] = {
{"ASK_DANGER","role=family_man,family_woman,family_youth|tmp=fresh,seasoned|st=friendly,neutral|world=road",{"Stay off the road after dark, things come out, we keep the doors shut","There was a man at the end of our street who wasn't right - I won't say more"}},
{"ASK_DANGER","role=family_man,family_woman,family_youth|tmp=fresh,seasoned|st=careful",{"The danger is getting too close to my kids - back off"}},
{"ASK_DANGER","role=family_elder|tmp=seasoned|st=friendly,neutral|world=water",{"The creek bottom, the dead seem to collect there - mind where you step"}},
{"ASK_DANGER","role=family_elder|tmp=seasoned|st=friendly,neutral|world=road",{"Strangers on the road scare me more than the sick ones - at least the sick ones are honest"}},
{"ASK_DANGER","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=friendly,neutral|world=road",{"The grocery store parking lot, fifty of them in there - I counted"}},
{"ASK_DANGER","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=friendly,neutral|world=window",{"Don't go through the neighborhood on Poplar, somebody's got a gun in every window"}},
{"ASK_DANGER","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=careful",{"You, you're the danger if you keep standing there"}},
{"ASK_DANGER","role=civilian_loner|tmp=seasoned|st=friendly,neutral|hour=16,22",{"Open fields at dusk - sound carries, they follow it"}},
{"ASK_DANGER","role=civilian_loner|tmp=seasoned|st=friendly,neutral|world=road",{"I stay off the roads, roads are where people and trouble meet"}},
{"ASK_DANGER","role=worker|tmp=seasoned|st=friendly,neutral|world=door",{"Stay off the loading docks at the plant, full of them, door's stuck open"}},
{"ASK_DANGER","role=worker|tmp=seasoned|st=friendly,neutral|world=vehicle",{"The truck stop on 31W has a gang now, pay or go around"}},
{"ASK_DANGER","role=worker|tmp=seasoned|st=careful",{"The danger's anyone who thinks I'm easy - I'm not"}},
{"ASK_DANGER","role=rescue_firefighter|tmp=seasoned|st=friendly,neutral|world=fire",{"Smoke over the north ridge - something's burning - avoid it"}},
{"ASK_DANGER","role=rescue_firefighter|tmp=seasoned|st=friendly,neutral",{"Gas leaks at the station on Main, one spark and it's over"}},
{"ASK_DANGER","role=rescue_medical|tmp=seasoned|st=friendly,neutral",{"Open wounds and dirty water, keep any cut clean, or it'll kill you slow","The hospital lot is a death trap - don't go in - don't even look"}},
{"ASK_DANGER","role=rescue_clergy|tmp=seasoned|st=friendly,neutral",{"Giving up is what'll kill you, keep your hope, friend"}},
{"ASK_DANGER","role=rescue_clergy|tmp=seasoned|st=friendly,neutral|world=water,road",{"Folks living on the edge of the river road, desperate people do desperate things"}},
{"ASK_DANGER","role=law_deputy,law_officer|tmp=seasoned|st=friendly,neutral",{"Looters on Main Street - armed - stay back from the hardware store","There's a group squatting in the old motel who won't answer the radio - avoid it"}},
{"ASK_DANGER","role=law_deputy,law_officer|tmp=seasoned|st=careful",{"Anybody who won't show their hands, that's who I'm watching"}},
{"ASK_DANGER","role=law_sheriff,law_sergeant|tmp=veteran|st=friendly,neutral|world=road",{"Armed crews on the highway, they're not the old drunks and teenagers anymore"}},
{"ASK_DANGER","role=law_sheriff,law_sergeant|tmp=veteran|st=friendly,neutral",{"Don't go near the Ekron cutoff, we lost two deputies there"}},
{"ASK_DANGER","role=law_trooper|tmp=veteran|st=friendly,neutral|world=cars",{"Interstate's a graveyard - Stalled cars, trapped people - stay off the shoulder"}},
{"ASK_DANGER","role=law_trooper|tmp=veteran|st=careful",{"Armed individuals - back away"}},
{"ASK_DANGER","role=law_corrections|tmp=seasoned|st=friendly,neutral",{"Escaped inmates, some of them are out and they're in no mood to be gentle"}},
{"ASK_DANGER","role=law_corrections|tmp=seasoned|st=careful",{"Anyone who approaches my post"}},
{"ASK_DANGER","role=swat_lead,swat_operator|tmp=veteran|st=friendly,neutral|world=window",{"Multi-story buildings, too many windows, too many places for something to wait"}},
{"ASK_DANGER","role=swat_lead,swat_operator|tmp=veteran|st=careful",{"Anyone who doesn't comply"}},
{"ASK_DANGER","role=soldier,soldier_green|tmp=seasoned,fresh|st=friendly,neutral|world=road",{"Don't wander off the road - Mines and strangers in equal numbers"}},
{"ASK_DANGER","role=soldier,soldier_green|tmp=seasoned,fresh|st=careful",{"Anybody who ignores a halt order"}},
{"ASK_DANGER","role=soldier_nco|tmp=veteran|st=friendly,neutral",{"Open ground - night, anything on foot - pick one"}},
{"ASK_DANGER","role=soldier_nco|tmp=veteran|st=friendly,neutral|hour=7,18",{"The ridge east of here is contested - don't move in daylight"}},
{"ASK_DANGER","role=soldier_nco|tmp=veteran|st=careful",{"Hostile, that's the only classification you need"}},
{"ASK_DANGER","role=deserter,militia|tmp=seasoned|st=friendly,neutral",{"Checkpoint patrols, they shoot first if they think you ran"}},
{"ASK_DANGER","role=deserter,militia|tmp=seasoned|st=careful",{"You, you'd be surprised how fast I can pull"}},
{"ASK_DANGER","role=elite_operator,elite_delta,mercenary|tmp=veteran|st=friendly,neutral",{"Everything, every sound, every shadow, learn to read the dark"}},
{"ASK_DANGER","role=elite_operator,elite_delta,mercenary|tmp=veteran|st=careful",{"Stay out of my way"}},
{"ASK_DANGER","role=outlaw|tmp=seasoned|st=friendly,neutral|world=road",{"Dead ones on the highway, and that bunch at the quarry - don't go there"}},
{"ASK_DANGER","role=outlaw|tmp=seasoned|st=friendly,neutral",{"The only danger worth worrying about is a man with a loaded gun and a bad day"}},
{"ASK_DANGER","role=outlaw|tmp=seasoned|st=careful",{"Right now? Me"}},
{"ASK_DANGER","role=raider,raider_boss|tmp=predator|st=friendly,neutral",{"Danger? You're standing in it, {g:buddy|lady} - Hah","The crews on 31W will gut you for a pair of boots"}},
{"ASK_DANGER","role=raider,raider_boss|tmp=predator|st=careful|world=inside",{"Danger's whoever thinks they can walk in here"}},
{"ASK_DANGER","role=gang_member,gang_boss|tmp=predator|st=friendly,neutral",{"The cut-through at the bridge, enemy set shoots anything that crosses"}},
{"ASK_DANGER","role=gang_member,gang_boss|tmp=predator|st=friendly,neutral|hour=16,5",{"Don't go downtown after dark, whole thing's a shooting gallery"}},
{"ASK_DANGER","role=gang_member,gang_boss|tmp=predator|st=careful",{"You're lookin' at it, {g:man|lady}"}},
{"ASK_DANGER","role=biker,biker_boss|tmp=predator,veteran|st=friendly,neutral|world=water,road",{"Chain across the road past the river, some of our own put it there"}},
{"ASK_DANGER","role=biker,biker_boss|tmp=predator,veteran|st=friendly,neutral",{"Rotters in the rest stop, went in once - lost a good brother"}},
{"ASK_DANGER","role=biker,biker_boss|tmp=predator,veteran|st=careful",{"You're riding in the wrong direction - turn around"}},
{"ASK_DANGER","role=crime_member|tmp=seasoned|st=friendly,neutral",{"There's a man in town who pays for fresh bodies - don't be fresh","The warehouse district belongs to the wrong people now - avoid it"}},
{"ASK_DANGER","role=crime_member|tmp=seasoned|st=careful",{"I'd avoid asking me that"}},
{"ASK_DANGER","role=prisoner|tmp=predator|st=friendly,neutral|world=road",{"Guards with rifles on the old state road, they'll cuff you or kill you"}},
{"ASK_DANGER","role=prisoner|tmp=predator|st=friendly,neutral",{"Everybody, {g:man|lady}, everybody's dangerous, me included"}},
{"ASK_DANGER","role=prisoner|tmp=predator|st=careful",{"I'm the danger if you keep pushing me"}},
{"ASK_DANGER","reg=law,swat|st=friendly,neutral|day=0,5",{"Everything that moves slow and moans - don't let them touch you","The infected - aim for the head, the living, too, everyone's scared and armed"}},
{"ASK_DANGER","role=civilian_man,civilian_woman|tmp=fresh|st=friendly,neutral",{"Everywhere! everything! the dead, the people, the noise, I don't know what's worse","Be quiet, that's the big one, they hear you, and then they all come","D-don't go anywhere you can't see out of, I learned that the hard way!!","Don't trust anyone who's too friendly, or too hungry, or too quiet, ugh, that's everyone","I don't know, I'm new at this, everything looks dangerous, and everything might be","Watch your back, they come from the sides, you think you're clear, and then there's three of them","Don't run unless you have to, running makes noise, I know that sounds crazy","Anything that moves, honestly, anything, even a branch, even a cat","S-stay AWAY from big groups, they attract more, and then you can't get out"}},
{"ASK_DANGER","role=civilian_man,civilian_woman|tmp=seasoned|st=friendly,neutral",{"The usual, the dead are slow but patient, and the living are fast but stupid","Big crowds of 'em now, one loud noise and they all come this way, so hush","The dead don't bother me so much as the folks who figured out you can take what you want","Don't go out alone, and if you must, tell somebody which way, so they know where to look for the body","Watch the sky... if it clouds over, the dead get bolder, I don't know why...","Whatever you hear, count to ten before you check, half the time it's nothing, half the time it's everything","The worst part is you get used to it, and used to is when you die"}},
{"ASK_DANGER","role=civilian_man,civilian_woman|st=friendly",{"Come stay close, and I'll point out what I know, there's three spots I won't go near","You're one of us, so I'll say it plain, the east side is rough, the west side is worse, and the middle is a trap","For you, because I like you, never trust a locked door that's already open"}},
{"ASK_DANGER","role=civilian_man,civilian_woman|st=careful",{"Anywhere you are, for starters","Leave -- that's my advice","I'm not telling you where it's safe, I'm telling you to go!!","Why -- you looking for a good place to ambush?"}},
{"ASK_DANGER","role=civilian_loner",{"Dead ones, plus the ones who figure they can take your stuff, the second kind is smarter","Water, don't drink standing water, I saw a man die from that, not from a bite, from water","Keep the racket down and watch the ground ahead. I don't trust a quiet stretch just because it's quiet","Anywhere with a big open yard, you'll see 'em coming, but they'll also see you","Don't cross open ground at dusk, that's when they stir, I'd bet money on it","Swamps, culverts, tunnels, you get cornered, and it's over","Lone men with a story, if a man tells you he's alone and begging, he's got three friends within shouting distance","Pack up before dark, always, I've never regretted leaving early"}},
{"ASK_DANGER","role=civilian_loner|st=careful",{"Danger is anywhere I'm not, so I'm leaving","Mind your own steps, friend","You're the danger, near as I can tell"}},
{"ASK_DANGER","role=family_man,family_woman,family_elder,family_youth|st=friendly,neutral",{"Keep the kids close, don't let 'em wander, they get curious, and curious is how they die","Watch for smoke, someone's burning something, and that's either a signal or a trap","The dead gather where it's quiet, don't ask me why, it's just what we've seen","Don't go near the wide streets, too open, stay on the backs, the alleys..","If you hear singing, don't go, it's not people singing"}},
{"ASK_DANGER","role=family_elder",{"Honey -- at my age everything is dangerous, a stair, a stone, a stranger...","Stay out of the dark, and stay in a group, that's the best I've got","Never go where you can't come back from, I learned that in '52"}},
{"ASK_DANGER","role=family_youth",{"Like, everything, I guess? The dead ones, guys with guns... the dark mostly","Don't trust anyone over thirty, ha, no, don't trust anyone who looks too clean","There's weird stuff out there, noises, shapes, I don't go out after sundown"}},
{"ASK_DANGER","role=worker",{"Wide open ground gets you picked off, I stay by a wall, always","Blind corners, and corners you can't see around, stop, listen, then go","Folks with a grudge... folks with guns, folks with nothing to lose, those are your three kinds of bad...","Gas leaks, wires down, flooded basements, the world's full of things that can kill you without teeth"}},
{"ASK_DANGER","role=rescue_medical",{"Any cut at all, clean it and wrap it, infection kills about as many as bites do","Dehydration, bad water, filthy hands, it's the boring things that kill you","Sleeping rough... in the cold, in the wet, don't do it, pneumonia is silent"}},
{"ASK_DANGER","role=rescue_clergy",{"Despair, my friend, that's the most dangerous thing out here, and it comes quietly","Isolation, don't wander alone, hear me, find someone, anyone, to keep you honest"}},
{"ASK_DANGER","role=rescue_firefighter",{"Smoke, fire, walls coming down... it all happens faster than you think","Stairwells... closets, basements, anywhere with one exit, the dead pile in there...","Gas... electric, structural, I check all three before I breathe"}},
{"ASK_DANGER","role=militia",{"Open lanes of fire, bad crossings, and strangers walking up too casual, that's my list","Everything within fifty yards that I can't identify, which is a lot...","Walk the edges, never the middle, and watch for the second guy, there's always a second guy"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=good,best",{"For you? I'd show you the safest way through, and who not to trust","Take what I say seriously, I wouldn't tell you this if I didn't care","Sit down, listen close, step by step, because I want you alive tomorrow","Careful, careful, friend, here's the straight truth, let me draw it out for you!","Of all people, you I'll warn: there's a pack in the east, armed, mean, moving at night","Worst of it's folks who think you owe 'em something, keep away from those","Stay off the main road, there's trouble at the junction, I've seen it with my own eyes","The old mill is crawling, don't go in, I lost a friend there!","There's a stretch past the cemetery, thick with them, go around","Mind your fire and your toes out there","A group's been grabbing travelers, quietly, one at a time, don't wander alone","I trust you with this: stay clear of high ground in town, there's a sniper, or a rumor of one","Watch the sky at dusk, when the birds go quiet, that's when it starts","Keep your voice low after sundown. I'd rather not advertise where we are","Folks are getting desperate, and desperate means dangerous, even the nice ones","Don't pick up anything shiny, there's tripwires, I'm not kidding","Take the long way round the school -- the gym's full of them","If you hear a bell -- don't answer, it's a lure","Shake your boots out every morning, learned that the hard way","Trust your gut, it's smarter than your brain right now","I'd walk with you if I could, I'd cover your back","Be careful with strangers, even kind ones, especially kind ones","The danger changes by the hour, so stay flexible","Bridges are bad, tunnels are worse, open ground is bad too, honestly everywhere is bad","There's a spot where the ground gives way, near the creek, I'd hate to lose you","You've survived this long, so you know, but I'll remind you: don't get comfortable","Moonless nights are the worst, you can't see them till they're touching you","Go out if you have to, just not alone","One more thing: if you get hurt, come find me, no questions","Avoid the south end, there's a group that doesn't welcome visitors","Eyes open and keep walking, that's about all I know","The biggest danger is the one you stop watching for!","I'd hate to lose you, so be careful, please"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=bad,worst",{"Nothing I'd TELL you","If I knew a trap, I wouldn't warn you"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=careful|rep=bad,worst",{"I'm not helping you, move on"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral|mood=fear",{"EVERYTHING! everything's dangerous, the dark is dangerous, the quiet is dangerous, you're dangerous, I'm sorry","I don't know, I don't know, I just keep waiting for something to jump out, anything, a leaf, a cat","Watch the corners, watch the shadows, watch your own feet, watch ME, I'm kidding, sort of","Don't go that way- not that way- I don't know why, I just have a feeling, a bad one","Behind you, behind you, always behind you, check behind you, constantly","The dead I understand... they're simple, it's the people that scare me!","They're everywhere- nowhere, then all of a sudden everywhere!"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral|mood=grim",{"Same stuff you've seen, just more of it","The dead I can predict, the living, no idea, so I watch both","Moving after dusk is the mistake that kills people... so don't make it","Everything wants something from you... your food, your boots, your blood, your time","The next mistake you make could be your last, so make it a small one"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=sad",{"The worst danger is losing hope... and I've come close, twice","Watch the ones you love, they're the ones who'll break your heart","Carelessness, it killed my husband, one careless step on a Tuesday","Grief, it makes you reckless, I'd know","The danger took my wife on the porch..","I think about the child I couldn't carry.."},false,false,{[5]={{t="ten feet from the door",afterMs=3500},{t="ten feet",afterMs=3000}},[6]={{t="that's the danger, in the end",afterMs=3500},{t="the choosing",afterMs=3000}}}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=angry",{"Idiots! idiots with guns, that's the danger, people who shoot at shadows and call it defense","Anything in a uniform that doesn't answer your questions, anything that points a rifle first","Dangerous? People who think they're in charge, God help us","The real danger's the idiots with guns who fire at shadows"},false,false,{[4]={{t="killed a boy that way, a sixteen-year-old, went out for water",afterMs=3500}}}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly|mood=warm",{"Stay by me, I've got a feel for when to duck and when to run","I've got your back, but you've got to promise me you'll watch your own, deal?","You worry me, you know that? don't do anything stupid out there"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"Well, there's the dead, the living, the dark, the dogs, the bears, and my cooking","Honestly? Boredom, then the sudden screaming, boredom, then screaming, repeat","Dangerous? Only if you take up the habit of trusting people","Biggest danger around here? My cooking","The danger? I've been doing this a whole week"},false,false,{[4]={{t="second biggest? My driving",afterMs=3000},{t="neither one is working these days",afterMs=3000}},[5]={{t="and I'm an expert on being scared",afterMs=3500}}}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=careful|mood=fear",{"You, for one, you're the danger, now go away","Everything's dangerous, and you're not helping"}},
{"ASK_DANGER","role=rescue_medical|st=friendly,neutral",{"Infection, mostly, every cut's a risk, every scrape is a door for something worse","Dehydration will drop you faster than any bite, drink, even when you don't want to","Don't touch what you can't wash, and don't eat anything you didn't cook yourself","Stay out of crowds... sick or well, the sick ones cough, the well ones cough later","Fever, chills, a headache that won't quit... tell somebody, don't hide it","Dead folks aren't all that's out there... flies, rats, the water, the cold.."}},
{"ASK_DANGER","role=rescue_medical|st=careful",{"Danger's anyone who gets near my patients, and that includes you"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=careful,neutral|rep=bad,worst",{"You're the danger, around here, go on","If you want danger, keep doing what you're doing","You're on your own out there, I'd watch myself","Everything is dangerous for a man like you!!","There's danger enough, and I won't help you find it or avoid it","Trouble follows you, and I don't want it near me","Danger? You carry it with you!","Ask the ones you wronged","Find it yourself","I hope you walk into every danger there is","I won't warn you, why would I?","The only thing dangerous around HERE is you","Yeah, good luck with that","You have a knack for finding trouble, so find some more","If something bites you, don't come to me","Do I look like your guide?","It's all danger -- go see for yourself","You'd never listen anyway","Cross the wrong people, and you'll know!","Dangerous? Let me think... no, I'm not helping","I'd sooner see you tested than tell you where","Seems you're doing fine at finding trouble","Don't tempt fate, or me","If you die out there -- I won't weep","I know where the danger is, and I'm not sharing","You made your bed","Danger's ahead, danger's behind, so pick your poison!","You won't survive on warnings from me","There's plenty, but I'm not your map","Somewhere out THERE is exactly what you deserve"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=recent_zombie_contact",{"THIS! this is the danger, right here, right now!","Them! Right there! Look! You see them? GET BEHIND ME","The danger's thirty feet away and closing, that's all you need to know","Danger? Everywhere, but especially THERE, to the left, don't look","Right now? Everything, move, quietly, move","You're standing in it, we both are, go, go","Don't panic, don't run, don't scream, back away, slowly","They're coming, that's the danger, that's always the danger","L-look sharp, and shut up, and walk","It's behind you- no- don't turn- just walk"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=player_armed",{"With that in your hands? Less than most, honestly","The biggest danger is when you run out of ammo, so, count","You've got teeth, so the danger's smaller, but it's still real","Keep that ready, you'll need it, soon"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral",{"Stay off open ground at dusk","Don't trust a house that's too quiet","The dead aren't the worst part","Keep your hand on your weapon, not on your door","Never drink from a still pond","Never go into a building you can't see out of","Watch the birds","Don't run in a straight line...","Be wary of anyone who smiles too much","Leave a way out behind you, always","If you hear a baby crying in an empty house","Don't light a fire after dark","Watch your feet","A dog barking means something's near","Don't sleep on the ground floor..","Quiet, always quiet, that's the big one","Don't take the main road","Watch for fresh tracks in the mud","Never trust a locked door","Stay away from the places with a lot of flies","If something looks too good to be true","Beware of the quiet, it's rarely empty..","Last Tuesday I went into a house to look for batteries","I watched a man open a pantry door in broad daylight","Don't pet strange dogs, I mean it","A woman waved me over from a porch -- so friendly..","Don't drink from the creek behind the old tannery","There's a spot on the back road where the fog sits in the morning","Never go into a barn alone","A boy offered to show me where the good cans were","I fell through a rotten porch and lay in the crawl space for an hour...","The worst part about gunshots isn't the noise","My neighbor died of a cut on his thumb","I lost a good friend to a swarm of wasps","Old wells","Stay out of the tall grass","The scariest night was when nothing came","There was a sound in the attic last week, scratching, soft, regular","Don't trust a quiet house with a clean porch","A group of men were walking in step down the road","I've seen a man shoot his own foot trying to be brave","Don't walk on fresh gravel"},false,false,{[1]={{t="I saw a man cross a field at dusk once",afterMs=3500},{t="I didn't see him cross the rest",afterMs=3000}},[2]={{t="and don't trust one that's too noisy, either",afterMs=3200},{t="the middle ones are fine",afterMs=3000}},[3]={{t="it's what people turn into when they're hungry",afterMs=3500}},[4]={{t="the door will betray you, the weapon won't",afterMs=3200}},[5]={{t="I did, once",afterMs=3200},{t="I don't want to talk about the next three days",afterMs=2800}},[6]={{t="you'll thank me, or you won't, and you'll be too dead to say so",afterMs=3500}},[7]={{t="when they go quiet, you've got about a minute",afterMs=3000}},[8]={{t="they don't tire, you do",afterMs=3200}},[9]={{t="a friendly stranger is the most dangerous thing out here",afterMs=3500}},[10]={{t="even when you think you're safe",afterMs=3500},{t="especially then",afterMs=3000}},[11]={{t="don't go in",afterMs=3500},{t="I learned that the hard way",afterMs=3000}},[12]={{t="I don't count on the dark to keep me hidden",afterMs=3200}},[13]={{t="there's more broken glass than you'd think",afterMs=3000}},[14]={{t="a dog going silent means something's closer",afterMs=3500}},[15]={{t="it's a rule, and a good one",afterMs=3200}},[16]={{t="the dead have good ears, the living have better",afterMs=3000}},[17]={{t="nothing good travels on the main road",afterMs=3500}},[18]={{t="somebody's moving -- and you don't know who",afterMs=3200}},[19]={{t="somebody locked it for a reason",afterMs=3200}},[20]={{t="you know what that means",afterMs=3500}},[21]={{t="it's a trap",afterMs=3200},{t="always a trap",afterMs=2800}},[23]={{t="the stairs creaked, and something upstairs answered",afterMs=3200},{t="I took the window, and I'm still picking glass out of my hands",afterMs=3000}},[24]={{t="he had a smile on his face, he found cans",afterMs=3500},{t="there was one behind the door too, he didn't smile after that",afterMs=3000}},[25]={{t="one bit my brother, and it wasn't even a dead one, just a scared one",afterMs=3200}},[26]={{t="I almost went",afterMs=3500},{t="then I saw the shotgun barrel on the swing behind her",afterMs=3000}},[27]={{t="a family of five did",afterMs=3200},{t="I heard the rest from a neighbor...",afterMs=2800}},[28]={{t="I walked right into six of them standing in it",afterMs=3500},{t="like they were waiting for a bus",afterMs=3000}},[29]={{t="honestly the nails get you more than the dead do",afterMs=3200},{t="I put one through my boot, and I was three miles from help",afterMs=2800}},[30]={{t="he was bait",afterMs=3500},{t="he cried when I wouldn't follow him",afterMs=3000},{t="I felt sick",afterMs=2800}},[31]={{t="listening to them walk over my head",afterMs=3500}},[32]={{t="it's the silence right after, when you wait to see who heard",afterMs=3200}},[33]={{t="a rusty nail, infection, a fever, three days",afterMs=3500},{t="nobody even bit him",afterMs=3000}},[34]={{t="he ran from the dead and straight into a nest",afterMs=3200},{t="bad luck compounds",afterMs=2800}},[35]={{t="someone put a plank over one, and it didn't hold",afterMs=3500},{t="that's all I'll say",afterMs=3000}},[36]={{t="you can't see what's in it, and neither can your dog",afterMs=3200}},[37]={{t="I sat there till dawn, knuckles white",afterMs=3500},{t="nothing, and I almost lost my mind",afterMs=3000}},[38]={{t="it was a raccoon",afterMs=3500},{t="I'm still not sure I'm over it",afterMs=3000}},[39]={{t="somebody's inside, and they swept it for a reason",afterMs=3200}},[40]={{t="very calm, very orderly",afterMs=3500},{t="I lay in a ditch for two hours after they passed",afterMs=3000}},[41]={{t="don't be brave, be boring",afterMs=3200}},[42]={{t="it crunches",afterMs=3500},{t="and everything within a hundred yards knows",afterMs=3000}}}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly",{"For you -- I'll draw a map in my head"},false,false,{[1]={{t="avoid the center of town, the river road, and anything with a red door",afterMs=3200}}}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=careful",{"Danger's whatever you walk into without knowing","You want a warning? Don't come near me","You, for starters","Everything","You want to know where danger is?","I'll worry about the danger","If you're asking, you're already in trouble","I won't tell a stranger where I'm weak","You're what's dangerous right now - stop there and tell me what you want","The danger around here is strangers who get too close - that ring any bells?"},false,{[10]="GENERIC"},{[3]={{t="I haven't decided yet",afterMs=3000}},[4]={{t="and nobody I'd tell you about",afterMs=2800}},[5]={{t="follow the next person who asks me",afterMs=3000}},[6]={{t="you worry about yourself",afterMs=3000}}}},
{"ASK_DANGER","role=civilian_loner|st=friendly,neutral",{"Water","Dusk","Anything that's too quiet","Roads","Dogs gone wild","Men with nothing to lose","Open meadows","Caves"},false,false,{[1]={{t="stand clear of standing water",afterMs=3500},{t="and downstream of any town",afterMs=3000}},[2]={{t="the dead get restless at dusk, same as deer",afterMs=3200}},[3]={{t="the woods talk, when they're right",afterMs=3500}},[4]={{t="never walk a road when a ditch will do",afterMs=3200}},[5]={{t="a pack of them is worse than a pack of the dead",afterMs=3500}},[6]={{t="they're the real danger",afterMs=3200}},[7]={{t="nowhere to hide, nowhere to run",afterMs=3500}},[8]={{t="they look like shelter",afterMs=3200},{t="they're graves",afterMs=2800}}}},
{"ASK_DANGER","role=family_elder|st=friendly,neutral",{"Dear, the danger is trusting your own legs on a stair","Watch where you step, there's glass","Don't go out after supper","The danger's in the cellar and the hayloft, they like the dark"},false,false,{[1]={{t="and then trusting a stranger",afterMs=3500},{t="in that order",afterMs=3000}},[2]={{t="and watch where you look, there's worse",afterMs=3200}},[3]={{t="nothing good walks after supper",afterMs=3500}},[4]={{t="always have",afterMs=3200}}}},
{"ASK_DANGER","role=family_elder|st=careful",{"You're the danger, {g:young man|young lady}"}},
{"ASK_DANGER","role=family_youth|st=friendly,neutral",{"So... everything, basically?","No basements, no splitting up, and never say I'll be right back","The dark is bad... the quiet is bad, and old houses are really bad","Adults who look too calm"},false,false,{[1]={{t="like, everything, everywhere, always",afterMs=3200}},[2]={{t="those are the rules, I watch movies",afterMs=3500}},[4]={{t="that's weird... right? that's a sign",afterMs=3200}}}},
{"ASK_DANGER","role=family_youth|st=careful",{"Dangerous? You, probably"}},
{"ASK_DANGER","role=worker|st=friendly,neutral",{"Machinery, if you're careless","Fumes","Rust","Live wires","Falling stock","Gas, electric, structural, I check all three before I go in anywhere"},false,false,{[1]={{t="a spinning blade doesn't care that the world ended",afterMs=3500}},[2]={{t="a closed shop with a leak will put you to sleep, and you won't wake up",afterMs=3200}},[3]={{t="cuts from rusty metal will kill you slow",afterMs=3500}},[4]={{t="downed lines in the wet",afterMs=3200},{t="stay clear",afterMs=2800}},[5]={{t="shelves, pallets, beams",afterMs=3500},{t="they come down without warning",afterMs=3000}}}},
{"ASK_DANGER","role=worker|st=careful",{"You're what I'm watching for"}},
{"ASK_DANGER","role=family_man,family_woman|st=friendly,neutral",{"Keep your children close","Open windows at night","Strangers"},false,false,{[1]={{t="a curious child is the most endangered thing alive",afterMs=3500}},[2]={{t="never mind the heat, close them",afterMs=3200}},[3]={{t="especially friendly ones",afterMs=3500}}}},
{"ASK_DANGER","role=family_man,family_woman|st=careful",{"You, to be honest!"}},
{"ASK_DANGER","role=rescue_clergy|st=friendly,neutral",{"Despair, my friend","Pride, too","Loneliness, in a crowd or alone","The dead aren't the danger"},false,false,{[1]={{t="it's the one thing we can fight with prayer",afterMs=3500}},[2]={{t="I've buried good men who thought they were invincible",afterMs=3200}},[3]={{t="it's an enemy that comes quietly",afterMs=3500}},[4]={{t="it's what happens to us watching them",afterMs=3200}}}},
{"ASK_DANGER","role=rescue_clergy|st=careful",{"You, perhaps"}},
{"ASK_DANGER","role=rescue_firefighter|st=friendly,neutral",{"Backdraft, flashover, collapse","Smoke","Gas","Stairwells","Roofs"},false,false,{[1]={{t="those are fire words, but they apply to every room now",afterMs=3500}},[2]={{t="it kills before the flames do",afterMs=3200}},[3]={{t="smell it... and run...",afterMs=3500}},[4]={{t="a chimney for the dead",afterMs=3200},{t="don't use them",afterMs=2800}},[5]={{t="if you're up there, know your way down",afterMs=3500}}}},
{"ASK_DANGER","role=rescue_firefighter|st=careful",{"Anyone who won't say what they want"}},
{"ASK_DANGER","role=militia|st=friendly,neutral",{"Fields of fire... blind corners, open water, and strangers who walk too casual","Anything that moves slow and doesn't groan is worse than anything that groans","Sound discipline","Ambush"},false,false,{[3]={{t="a dropped canteen could cost a squad",afterMs=3500}},[4]={{t="always ambush",afterMs=3200}}}},
{"ASK_DANGER","role=militia|st=careful",{"You, until I know otherwise"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,3",{"Everything's dangerous... but it's new, so everyone's a mess, including them...","It's chaos out there, absolute chaos, stay away from crowds","Panic is the biggest danger right now"},false,false,{[3]={{t="people do stupid things when they panic",afterMs=3500}}}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|day=4,14",{"The first wave of panic has passed, now it's the hunger that's dangerous","People are getting desperate"},false,false,{[2]={{t="and desperate people are armed",afterMs=3200}}}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|day=15,99999",{"I've stopped expecting this to get easier. You learn a bit, then something else goes wrong","The dead I can handle, it's the living that have started hunting","Routine is the danger, you stop paying attention"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=22,4",{"Right now? The dark, the dark is the danger, it hides everything","It's night, it's night, they see better than we do, stay inside","Don't light anything, don't talk, don't move, wait for first light","Everything with teeth comes out at night, the dead are the least of it","You're out in the middle of the night, that's the danger, you're the danger..."}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=5,10",{"Morning's gentle, but don't trust it","The dead are slow at dawn, but the living are hungry","Early's the best time to move, but take your time, a rushed step is a loud step"},false,false,{[1]={{t="they're slow to wake, not gone",afterMs=3500}}}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=11,18",{"Sun's high, which means we can see them, and they can see us","Midday heat'll knock you flat, so drink up and find some shade","Midday's quiet, but quiet isn't safe"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=19,21",{"Dusk is coming, and dusk is the worst, get inside","The light's going... so the danger is -- soon","Evening's when they stir, I'd find a roof"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=fear",{"I hear footsteps even when I'm alone","I keep a rope tied to my ankle at night"},false,false,{[1]={{t="I think it's my own",afterMs=3500},{t="I hope it's my own",afterMs=3000}},[2]={{t="the other end's tied to the bed",afterMs=3200},{t="I know how it sounds",afterMs=2800}}}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=friendly|hour=16,5",{"Stay near me tonight"},false,false,{[1]={{t="I know this stretch, I've lost enough to learn it",afterMs=3200}}}},
{"ASK_DANGER","reg=raider|st=neutral,careful",{"Dangerous? Yeah, it is, and right now it's mostly me you need to worry about","Everything's dangerous, {g:pal|lady}, the dead, the living, the weather, your own stupid feet","Keep off the open ground and the roads, and stay the hell away from me","Wherever you're walking, there's somebody ready to take your stuff, I just happen to be the one talking","Careful, you're standing in the middle of my territory, and my people don't like surprises","Danger? It's the end of the world, what did you expect, a picnic?"}},
{"ASK_DANGER","reg=raider|st=hostile",{"Danger? You're in it, you moron!","You want to know what's dangerous? Me, right now, today!"}},
{"ASK_DANGER","reg=raider|st=friendly",{"Honestly? Be careful, {g:man|lady}, they come out of nowhere, I almost got bitten twice earlier today, scared the shit out of me","Don't go anywhere alone, don't make noise, and don't trust anyone, myself included"}},
{"ASK_DANGER","role=raider_boss,gang_boss,biker_boss|st=neutral,careful",{"Danger is where the profit is, and I'm in the business"}},
{"ASK_DANGER","reg=gang|st=neutral,careful",{"Dangerous? Man, it's hell out here, the dead, the cops, the crews, everybody wants a piece","Watch your back, there's always someone looking to jump you","Main road's bad, don't be seen, and stay off the corner","Don't go out in the dark alone, and don't trust nobody smiling too much","Dead ones don't scare me, it's the living I watch"}},
{"ASK_DANGER","reg=gang|st=hostile",{"Danger's right in front of you, step back"}},
{"ASK_DANGER","reg=gang|st=friendly",{"Watch yourself, I've seen what happens to people who don't"}},
{"ASK_DANGER","reg=club|st=neutral,careful",{"Everything's dangerous, but some things are stupider than others","Don't make noise, and don't put that weapon down for nothing","Stay off the highway unless you want to get shot at, and I'm not exaggerating","Don't go anywhere you can't get out of fast, learned that the hard way"}},
{"ASK_DANGER","reg=club|st=hostile",{"You're the most dangerous thing I've seen all day, and that's not a compliment"}},
{"ASK_DANGER","reg=club|st=friendly",{"Listen, {g:brother|sister}, the places that look safe are the ones that'll kill you"}},
{"ASK_DANGER","reg=crime|st=neutral,careful",{"Danger is relative, and I intend to be on the safe side of it","It's a dangerous time for everyone, I'd advise you to be discreet","Assume every stranger is armed, hungry, and desperate, I do"}},
{"ASK_DANGER","reg=crime|st=friendly",{"I'd take care if I were you, I'd hate to see something happen"}},
{"ASK_DANGER","reg=prison|st=neutral,careful",{"Dangerous? You bet, everything wants to kill us, even the quiet","Don't go anywhere you can't run from, don't stay anywhere you can't hide","I'd tell you to be careful, but careful doesn't mean much anymore"}},
{"ASK_DANGER","reg=prison|st=hostile",{"Don't come near me, that's the danger, I'll hurt you!"}},
{"ASK_DANGER","reg=prison|st=friendly",{"Please be careful, it's so easy to die out here"}},
{"ASK_DANGER","reg=outlaw|st=neutral,careful",{"Danger is everywhere, but mostly where people are","The dead I can handle, it's the living that scare me","Tracks, smoke, sudden quiet - that's what I watch for"}},
{"ASK_DANGER","reg=outlaw|st=friendly",{"If you're going out, don't go alone, I wouldn't"}},
{"ASK_DANGER","role=deserter|st=neutral,careful",{"Stay away from the main roads, the Army's on them, and they don't ask questions"}},
{"ASK_DANGER","reg=law|st=neutral,careful",{"The area is dangerous, I'd advise you to stay indoors","Multiple hostile incidents have been reported, please proceed with caution","Armed groups are operating in the area, avoid them if you can","We've had reports of looting and violence, stay vigilant"}},
{"ASK_DANGER","reg=law|st=hostile",{"You're in a restricted area, you need to leave"}},
{"ASK_DANGER","reg=law|st=friendly",{"It's bad out there, stay with us if you need protection"}},
{"ASK_DANGER","role=law_sheriff|st=neutral,careful",{"Everything within the county line is dangerous, and I'd advise you not to push your luck"}},
{"ASK_DANGER","reg=military|st=neutral,careful",{"Area is considered hostile","Stay within designated safe areas","Civilians are advised to remain indoors"}},
{"ASK_DANGER","reg=military|st=hostile",{"This is a restricted zone, return to your shelter immediately"}},
{"ASK_DANGER","reg=military|st=friendly",{"It's rough, but we're doing our best to keep the area secure"}},
{"ASK_DANGER","role=soldier_nco|st=neutral,careful",{"Do exactly what you're told and you might live"}},
{"ASK_DANGER","role=soldier_green|st=neutral,careful",{"It's... really scary, I haven't slept in two days, you should be careful"}},
{"ASK_DANGER","reg=elite|st=neutral,careful",{"Everything is a threat, act accordingly"}},
{"ASK_DANGER","role=mercenary|st=neutral,careful",{"The danger is whoever has the bigger gun, I make sure it's me"}},
{"ASK_DANGER","role=militia|st=neutral,careful",{"Raiders been seen on the east road, I'd stay clear","Stay off the roads at dusk, and don't go near the woods if you can help it","We lost two men to the dead last week, so keep your guard up"}},
{"ASK_DANGER","role=militia|st=friendly",{"Come inside, friend, it's safer with us"}},
{"ASK_DANGER","reg=civilian,family|tmp=fresh|st=friendly,neutral",{"Everything! The dogs have gone wild too, whole packs of them off the farms - everything's dangerous now","There's a lot of them around the gas station, and a man with a shotgun on Elm who doesn't talk first - be careful, okay?"},false,{[2]="GENERIC"}},
{"ASK_DANGER","reg=civilian,family|tmp=fresh|st=friendly,neutral|world=door",{"Don't go in houses with the front door open, that's what I learned, an open door means they already got in"}},
{"ASK_DANGER","reg=civilian,family|tmp=fresh|st=friendly,neutral|day=0,7",{"People are scared and they've all got guns, that's the dangerous part, them too, but mostly the guns"}},
{"ASK_DANGER","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral|world=road",{"Dead in the houses, bad folks on the roads, heat stroke in the fields - pick your poison and carry water"}},
{"ASK_DANGER","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral",{"A store that isn't picked clean is untouched for a reason - something's sitting in it","Don't sit down in tall grass, you don't know what's lying in it, or how long it'll stay lying down"}},
{"ASK_DANGER","reg=civilian,family,worker|tmp=seasoned,veteran|st=friendly,neutral",{"Everything's dangerous, so you rank it, living groups first, crowds of dead second, being dumb third"}},
{"ASK_DANGER","reg=civilian,family,worker,rescue|st=hostile",{"Me, I'm what's dangerous around here - turn around"}},
{"ASK_DANGER","reg=worker|st=friendly,neutral",{"Stay off the railroad trestle, boards are rotten, and there's always something underneath it in the shade","Old quarry pit out past town filled up with rainwater and they fall in - you hear 'em splashing all night, don't go look"}},
{"ASK_DANGER","reg=rescue|role=rescue_medical|st=friendly,neutral|world=window",{"Rusty metal and broken glass, a tetanus shot's a luxury now - a cut foot kills you slower, but it kills you"}},
{"ASK_DANGER","reg=rescue|role=rescue_firefighter|st=friendly,neutral|world=building,fire",{"Gas leaks, half the houses in {town} have a stove knob turned with no flame - Sniff before you strike a match indoors"}},
{"ASK_DANGER","reg=rescue|role=rescue_clergy|st=friendly,neutral",{"I tell folks the dead are slow and the living are clever - fear the clever ones"}},
{"ASK_DANGER","reg=law,swat|st=friendly,neutral",{"{sir}, the biggest danger is folks who've decided the rules don't apply anymore - and the dead, but you knew that"}},
{"ASK_DANGER","reg=law|st=friendly,neutral|day=5,9999",{"We've had three shootings over gas cans this week - don't carry one where people can see it"}},
{"ASK_DANGER","reg=law|tmp=seasoned,veteran|st=friendly,neutral|hour=16,5|world=water",{"Stay out of the river bottoms after dark, we lost a man down there and never found enough of him to bury"}},
{"ASK_DANGER","reg=law,swat|st=careful,hostile",{"I'm the danger you need to think about if you don't back up"}},
{"ASK_DANGER","reg=military|st=friendly,neutral|world=road",{"Civilians shooting at anything that moves, crowds on the main roads - and us, if you come near the perimeter"}},
{"ASK_DANGER","reg=military|st=friendly,neutral|day=6,9999|world=road",{"Keep off the highway, checkpoints shoot first now - I'm not proud of that"}},
{"ASK_DANGER","reg=elite",{"Be careful approaching strangers. I can't tell you what every group will do"}},
{"ASK_DANGER","reg=military|st=careful,hostile",{"Most dangerous spot in the county right now is the end of my barrel - step off it"}},
{"ASK_DANGER","reg=outlaw,raider|st=friendly,neutral",{"For you? Just about everything - me included"}},
{"ASK_DANGER","reg=crime|st=friendly,neutral|world=road",{"Couple crews working the roads, I'd tell you which, but information costs - you buying?"},false,{[1]="TRADE_OFFER"}},
{"ASK_DANGER","reg=prison|st=friendly,neutral|world=road",{"Guys I came out with, some were in for real bad things - stay off the prison road"}},
{"ASK_DANGER","reg=gang|st=friendly,neutral|world=water,road",{"The bikers on the river road, they'll run you down for fun - us, we're businessmen"}},
{"ASK_DANGER","reg=club|st=friendly,neutral",{"City kids up from Louisville with their daddies' pistols, they shoot sideways and hit everybody but who they're aiming at"}},
{"ASK_DANGER","reg=outlaw,raider,gang,club,crime,prison|st=careful,hostile",{"Yeah, you walked right into it"}},
{"ASK_DANGER","reg=outlaw,raider,gang,club,crime,prison|st=hostile",{"What's out there ain't half as bad as what's standing right here","You leaving, or do you want a demonstration?"},false,{[2]="LEAVE_NOW"}},
{"ASK_DANGER","reg=civilian|tmp=fresh|st=friendly,neutral",{"The bend past the bridge - don't ask me why, just don't take the bend"}},
{"ASK_DANGER","reg=worker|tmp=seasoned|st=neutral|mood=grim|world=cars",{"Anywhere cars are stopped in both lanes... nobody's in 'em, folks just stopped"}},
{"ASK_DANGER","role=rescue_medical|st=neutral",{"The heat, everybody's watching for teeth and it's the heat dropping people"}},
{"ASK_DANGER","role=law_deputy|st=neutral",{"Ask where somebody slept. If they won't even tell you that, don't be in a hurry to trust them"}},
{"ASK_DANGER","role=soldier_nco|tmp=veteran|st=neutral|hour=16,22",{"Open ground at dusk, everything hunts at once and you're the slowest thing out there"}},
{"ASK_DANGER","role=elite_delta|tmp=veteran|st=neutral",{"What you'll miss is other people, you'll look at them and decide they're fine"}},
{"ASK_DANGER","role=family_elder|st=neutral,friendly|world=water",{"Creek's low and it smells wrong - don't let anybody drink out of that creek"}},
{"ASK_DANGER","role=civilian_loner|st=careful|mood=grim|world=building",{"There's a stretch where every mailbox has got something in it - I quit going that way"}},
{"ASK_DANGER","reg=raider,gang|tmp=predator|st=hostile",{"Right now? Me, I'm what's dangerous round here, glad we got that settled"}},
{"ASK_DATE","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"It's {weekday} -- I think, {date}, it ALL runs together, though, it feels like Friday was yesterday","{weekday}... {date} -- don't ask me what year, I'd say 1993, but I'm not sure of anything","{date}, I think, it's the kind of thing you'd never forget, and I did, in two days","{weekday}, which I only know because I marked it on my arm with a pen, look","I don't know... {weekday}? {date}? I lost count somewhere around the second night!","It's {weekday}, the {date}, and I keep thinking somebody's going to come and say it was all a drill"}},
{"ASK_DATE","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"{weekday}, {date}, give or take, I keep a tally on the wall, one mark a day, it's all I've got","{date}... same as always -- just another day in a long string of them","{weekday}... I think, you lose track, but there's a rhythm to it, even now","By my count it's {weekday}... {date}, but the calendar is a liar these days...","{weekday}, and nothing changes, nothing changes at all"}},
{"ASK_DATE","reg=civilian,family,worker,rescue|st=friendly",{"{weekday}, {date}. Don't ask me why I still keep track, but I do","It's {weekday}, my friend, if I'm right, and I usually am!"}},
